sections.body:
# count : N copies numérotées (index fragile)
resource "aws_instance" "web" {
  count         = 3
  instance_type = "t3.micro"
  tags = { Name = "web-${count.index}" }
}

# for_each : une instance par clé (identité stable)
resource "aws_instance" "app" {
  for_each      = toset(["api", "worker", "cron"])
  instance_type = "t3.micro"
  tags = { Name = each.key }        # each.key / each.value
}

resource "aws_db_instance" "prod" {
  # ... configuration ...
  lifecycle {
    prevent_destroy = true        # empêche un destroy accidentel
    ignore_changes  = [password]  # un autre système gère le mot de passe
  }
}

resource "aws_instance" "web" {
  # ... configuration ...
  lifecycle {
    create_before_destroy = true  # remplacement sans coupure
  }
}

# Le meta-argument provider : choisir une instance de provider (alias)
#   provider = aws.europe

# Un module instancié par environnement
module "stack" {
  for_each    = toset(["dev", "staging", "prod"])
  source      = "./modules/stack"
  environment = each.key
}
output "prod_url" { value = module.stack["prod"].url }

# Migrer count -> for_each sans recréer (bloc moved par élément)
moved {
  from = aws_instance.web[0]
  to   = aws_instance.web["api"]
}
